mapper.select:
select wf.enabled and (
    (wf.version = #{workflowVersion} and wf.schedule_enabled) or exists (
        select 1 from batch.scheduled_occurrence occurrence
        where occurrence.tenant_id = wf.tenant_id
          and occurrence.workflow_definition_id = wf.id
          and occurrence.scheduled_fire_time = #{scheduledFireTime}
          and occurrence.occurrence_status = 'WAITING_READINESS'
    )
) as admitted
from batch.workflow_definition wf
where wf.tenant_id = #{tenantId} and wf.id = #{workflowDefinitionId}
for share of wf

select exists (
    select 1 from batch.workflow_definition
    where tenant_id = #{tenantId}
      and id = #{workflowDefinitionId}
      and version = #{workflowVersion}
)

select exists (
    select 1
    from batch.workflow_definition
    where tenant_id = #{tenantId}
      and id = #{workflowDefinitionId}
      and enabled = true
)

select *
from batch.trigger_request
where tenant_id = #{tenantId}

    and job_code = #{jobCode}


    and trigger_type = #{triggerType}


    and request_status = #{requestStatus}

order by id desc

select *
from batch.trigger_request
where tenant_id = #{tenantId}
  and request_id = #{requestId}

select * from batch.trigger_request
where tenant_id = #{tenantId}
  and workflow_definition_id = #{workflowDefinitionId}
  and external_event_source = #{externalEventSource}
  and external_event_id = #{externalEventId}

select workflow_definition_id
from batch.trigger_request
where tenant_id = #{tenantId}
  and external_event_source = #{externalEventSource}
  and external_event_id = #{externalEventId}
order by workflow_definition_id
for update

select case
           when cast(#{bizDate,jdbcType=DATE} as date) is null
                or target.calendar_code is null then 0::bigint
           else batch.acquire_batch_day_settlement_fence(
               #{tenantId}, target.calendar_code, #{bizDate,jdbcType=DATE})
       end
  from (
      select coalesce(
                 (select workflow.calendar_code
                    from batch.workflow_definition workflow
                   where workflow.tenant_id = #{tenantId}
                     and workflow.id = #{workflowDefinitionId}),
                 (select job.calendar_code
                    from batch.job_definition job
                   where job.tenant_id = #{tenantId}
                     and job.job_code = #{jobCode})
             ) as calendar_code
  ) target

mapper.update:
update batch.trigger_request
set request_status = #{requestStatus},
    updated_at = current_timestamp
where tenant_id = #{tenantId}
  and request_id = #{requestId}

update batch.trigger_request
set request_status = #{requestStatus},
    updated_at     = current_timestamp
where tenant_id      = #{tenantId}
  and request_id     = #{requestId}
  and request_status = #{expectedStatus}
